tag.script.11@html
@js:
let met = result.match(/if \('(.*?)'/)[1];
	java.log(met);
if(met=='aes'){
let data = result.match(/decrypt\('(.*?)'/)[1];
let key = result.match(/parse\('(.*?)'/)[1];
key = java.base64DecodeToByteArray(key);
java.getElement('id.content@div.1')+java.bytesToStr(java.createSymmetricCrypto("AES/ECB/pkcs7padding", key).decrypt(data));}else{
	let data = result.match(/atob\('(.*?)'/)[1];
java.getElement('id.content@div.1')+java.base64Decode(data);
	}

